1	# Nxeon primary domain — nxeon.cloud (added during the revsports.ca → nxeon.cloud migration).
2	# Additive to the generated `nxeon` vhost so the cutover is reversible. The admin
3	# ops portal stays on its existing secret subdomain until its DNS is moved.
4	
5	# HTTP -> HTTPS (ACME challenge still served)
6	server {
7	    listen 80;
8	    listen [::]:80;
9	    server_name nxeon.cloud www.nxeon.cloud;
10	    location /.well-known/acme-challenge/ { root /var/www/certbot; }
11	    location / { return 301 https://$host$request_uri; }
12	}
13	
14	# Customer portal — https://nxeon.cloud
15	server {
16	    listen 443 ssl;
17	    listen [::]:443 ssl;
18	    http2 on;
19	    server_name nxeon.cloud www.nxeon.cloud;
20	    ssl_certificate /etc/letsencrypt/live/nxeon.cloud/fullchain.pem;
21	    ssl_certificate_key /etc/letsencrypt/live/nxeon.cloud/privkey.pem;
22	    ssl_protocols TLSv1.2 TLSv1.3;
23	    ssl_ciphers HIGH:!aNULL:!MD5;
24	    client_max_body_size 20m;
25	    location /admin { return 404; }
26	    location ~ ^/(login|register|forgot-password|reset-password)$ {
27	        limit_req zone=nxeon_auth burst=15 nodelay;
28	        proxy_pass http://127.0.0.1:3000;
29	        proxy_http_version 1.1;
30	        proxy_set_header Host $host;
31	        proxy_set_header X-Real-IP $remote_addr;
32	        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
33	        proxy_set_header X-Forwarded-Proto $scheme;
34	        proxy_set_header Upgrade $http_upgrade;
35	        proxy_set_header Connection "upgrade";
36	    }
37	    location /console-ws {
38	        proxy_pass http://127.0.0.1:8899/console;
39	        proxy_http_version 1.1;
40	        proxy_set_header Upgrade $http_upgrade;
41	        proxy_set_header Connection "upgrade";
42	        proxy_set_header Host $host;
43	        proxy_read_timeout 3600s;
44	    }
45	    location /terminal-ws {
46	        proxy_pass http://127.0.0.1:8901;
47	        proxy_http_version 1.1;
48	        proxy_set_header Upgrade $http_upgrade;
49	        proxy_set_header Connection $connection_upgrade;
50	        proxy_set_header Host $host;
51	        proxy_read_timeout 3600s;
52	        proxy_send_timeout 3600s;
53	        proxy_buffering off;
54	    }
55	    location / {
56	        proxy_pass http://127.0.0.1:3000;
57	        proxy_http_version 1.1;
58	        proxy_set_header Host $host;
59	        proxy_set_header X-Real-IP $remote_addr;
60	        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
61	        proxy_set_header X-Forwarded-Proto $scheme;
62	        proxy_set_header Upgrade $http_upgrade;
63	        proxy_set_header Connection "upgrade";
64	    }
65	}
